UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Si sommano tutte le <strong>attività</strong> (conti, investimenti, immobili, eventuali altri beni di valore) e si sottraggono tutte le <strong>passività</strong> (debito residuo del mutuo, prestiti, carte di credito revolving). Il risultato può essere sorprendente in entrambe le direzioni: due persone con lo stesso stipendio possono avere patrimoni netti molto diversi in base a quanto debito portano e quanto hanno accumulato.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Si sommano tutte le <strong>attività</strong> (conti, investimenti, immobili, eventuali altri beni di valore) e si sottraggono tutte le <strong>passività</strong> (debito residuo del mutuo, prestiti, carte di credito revolving). Il risultato può essere sorprendente in entrambe le direzioni: due persone con lo stesso stipendio possono avere patrimoni netti molto diversi in base a quanto debito portano e quanto hanno accumulato.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Esempio di patrimonio netto (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Voce</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Importo</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Conto corrente e deposito</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">8.000</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Investimenti</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">25.000</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Casa</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">220.000</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Mutuo, debito residuo</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">−140.000</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Finanziamento auto</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">−6.000</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5 font-semibold text-gray-900">Patrimonio netto</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono font-semibold text-gray-900">107.000</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">La casa conta al suo valore di mercato, il mutuo per il debito che resta da restituire, non per la rata.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'patrimonio-netto-cos-e-perche-seguirlo-nel-tempo' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il tasso di risparmio è la percentuale del reddito netto che riesci a mettere via ogni mese, invece di spendere: (reddito netto meno spese totali) diviso reddito netto. Chi guadagna 2.500€ e ne spende 2.000€ ha un tasso di risparmio del 20%; chi ne guadagna 4.000€ ma ne spende 3.900€ ha un tasso di risparmio di appena il 2,5%, nonostante uno stipendio molto più alto.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il tasso di risparmio è la percentuale del reddito netto che riesci a mettere via ogni mese, invece di spendere: (reddito netto meno spese totali) diviso reddito netto. Chi guadagna 2.500€ e ne spende 2.000€ ha un tasso di risparmio del 20%; chi ne guadagna 4.000€ ma ne spende 3.900€ ha un tasso di risparmio di appena il 2,5%, nonostante uno stipendio molto più alto.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Stipendio e tasso di risparmio (importi in euro al mese)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Reddito netto</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Spese</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Risparmio</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Tasso</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">2.500</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">2.000</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">500</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">20%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">4.000</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">3.900</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">100</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">2,5%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">1.800</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1.530</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">270</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">15%</td></tr></tbody></table></div></figure>'),
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Nella comunità <a href="/news/indipendenza-finanziaria-fire-come-calcolare-il-numero" class="text-accent hover:underline font-medium">FIRE</a> il tasso di risparmio è la variabile più discussa, perché incide su due fronti contemporaneamente: un tasso di risparmio più alto significa sia più capitale accumulato ogni mese, sia una spesa mensile futura più bassa da coprire una volta smesso di lavorare — le due leve si rafforzano a vicenda, il che spiega perché un aumento anche modesto del tasso di risparmio possa accorciare gli anni necessari per raggiungere l''indipendenza finanziaria in modo più che proporzionale.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Nella comunità <a href="/news/indipendenza-finanziaria-fire-come-calcolare-il-numero" class="text-accent hover:underline font-medium">FIRE</a> il tasso di risparmio è la variabile più discussa, perché incide su due fronti contemporaneamente: un tasso di risparmio più alto significa sia più capitale accumulato ogni mese, sia una spesa mensile futura più bassa da coprire una volta smesso di lavorare — le due leve si rafforzano a vicenda, il che spiega perché un aumento anche modesto del tasso di risparmio possa accorciare gli anni necessari per raggiungere l''indipendenza finanziaria in modo più che proporzionale.</p><figure class="my-6 rounded-xl border border-border bg-white p-5"><figcaption class="mb-4 text-sm font-semibold text-gray-900">Anni di lavoro per raggiungere l''indipendenza finanziaria</figcaption><div class="space-y-3"><div><div class="mb-1 flex justify-between gap-3 text-sm"><span class="text-gray-700">Tasso di risparmio del 10%</span><span class="whitespace-nowrap font-mono text-gray-900">51 anni</span></div><div class="h-2.5 rounded-full bg-gray-100"><div class="h-2.5 rounded-full bg-accent" style="width:100.0%"></div></div></div><div><div class="mb-1 flex justify-between gap-3 text-sm"><span class="text-gray-700">Tasso di risparmio del 20%</span><span class="whitespace-nowrap font-mono text-gray-900">37 anni</span></div><div class="h-2.5 rounded-full bg-gray-100"><div class="h-2.5 rounded-full bg-accent" style="width:71.5%"></div></div></div><div><div class="mb-1 flex justify-between gap-3 text-sm"><span class="text-gray-700">Tasso di risparmio del 30%</span><span class="whitespace-nowrap font-mono text-gray-900">28 anni</span></div><div class="h-2.5 rounded-full bg-gray-100"><div class="h-2.5 rounded-full bg-accent" style="width:54.5%"></div></div></div><div><div class="mb-1 flex justify-between gap-3 text-sm"><span class="text-gray-700">Tasso di risparmio del 40%</span><span class="whitespace-nowrap font-mono text-gray-900">22 anni</span></div><div class="h-2.5 rounded-full bg-gray-100"><div class="h-2.5 rounded-full bg-accent" style="width:42.1%"></div></div></div><div><div class="mb-1 flex justify-between gap-3 text-sm"><span class="text-gray-700">Tasso di risparmio del 50%</span><span class="whitespace-nowrap font-mono text-gray-900">17 anni</span></div><div class="h-2.5 rounded-full bg-gray-100"><div class="h-2.5 rounded-full bg-accent" style="width:32.4%"></div></div></div><div><div class="mb-1 flex justify-between gap-3 text-sm"><span class="text-gray-700">Tasso di risparmio del 60%</span><span class="whitespace-nowrap font-mono text-gray-900">12 anni</span></div><div class="h-2.5 rounded-full bg-gray-100"><div class="h-2.5 rounded-full bg-accent" style="width:24.2%"></div></div></div></div><p class="mt-4 text-xs text-muted">Partendo da zero, con un rendimento reale ipotetico del 5% annuo e un capitale obiettivo di 25 volte la spesa annua (regola del 4%). Passare dal 10% al 20% fa risparmiare circa 14 anni.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'tasso-di-risparmio-cosa-e-come-calcolarlo' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Con un''inflazione media del 2,5% annuo, 10.000&euro; tenuti fermi su un conto che non matura interessi valgono, in termini di potere d''acquisto reale, circa 7.800&euro; dopo 10 anni e circa 6.100&euro; dopo 20 anni. Il numero sul conto non è cambiato: è cambiato quanto puoi comprarci.</p>',
