UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Per la sola rata del nuovo mutuo, la prassi bancaria italiana (in linea con le indicazioni prudenziali di Banca d''Italia) considera generalmente sostenibile una rata che non superi circa il <strong>30-35% del reddito netto familiare</strong>. Non è una regola scritta nella legge in modo identico ovunque, ma è la soglia oltre la quale la maggior parte degli istituti inizia a valutare la richiesta come più rischiosa, a prescindere dal merito creditizio generale del richiedente.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Per la sola rata del nuovo mutuo, la prassi bancaria italiana (in linea con le indicazioni prudenziali di Banca d''Italia) considera generalmente sostenibile una rata che non superi circa il <strong>30-35% del reddito netto familiare</strong>. Non è una regola scritta nella legge in modo identico ovunque, ma è la soglia oltre la quale la maggior parte degli istituti inizia a valutare la richiesta come più rischiosa, a prescindere dal merito creditizio generale del richiedente.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Reddito netto di 2.500 euro: come sale il DTI (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5"></th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Rata</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Rate totali</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">DTI</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Solo la rata del mutuo</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">700</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">700</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">28%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Più il finanziamento auto</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">250</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">950</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">38%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Più un prestito personale</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">150</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1.100</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">44%</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Con il solo mutuo il DTI resta sotto la soglia indicativa del 30-35%; con le altre rate la supera, anche se ogni singola rata sembra sostenibile.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'rapporto-debito-reddito-dti-cosa-e' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Non esiste un numero universale: dipende da quanto vuoi vivere una volta smesso di lavorare, da quanti anni mancano alla pensione pubblica e da quanto già versato in forme integrative (fondo pensione negoziale, PIP, o investimenti personali dedicati a questo scopo). Quello che conta davvero è iniziare presto: per l''effetto dell''interesse composto, versare la stessa cifra a 30 anni invece che a 45 può tradursi in un capitale finale molto più alto, a parità di sforzo mensile.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Non esiste un numero universale: dipende da quanto vuoi vivere una volta smesso di lavorare, da quanti anni mancano alla pensione pubblica e da quanto già versato in forme integrative (fondo pensione negoziale, PIP, o investimenti personali dedicati a questo scopo). Quello che conta davvero è iniziare presto: per l''effetto dell''interesse composto, versare la stessa cifra a 30 anni invece che a 45 può tradursi in un capitale finale molto più alto, a parità di sforzo mensile.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">100 euro al mese fino a 67 anni (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Inizi a</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Versato</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Capitale a 67 anni</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">25 anni</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">50.400</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">130.518</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">30 anni</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">44.400</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">101.464</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">35 anni</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">38.400</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">77.670</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">45 anni</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">26.400</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">42.221</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">55 anni</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">14.400</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">18.444</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Rendimento ipotetico del 4% annuo, al netto dei costi; tasse e vantaggi fiscali esclusi.</p></figure>'),
    updated_at = NOW()
