UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">È una stima statistica basata su dati storici passati (soprattutto mercato americano del Novecento), non una promessa: sequenze di rendimenti negativi nei primi anni di prelievo (il cosiddetto «sequence risk») possono ridurre la probabilità di successo. Molti nella comunità FIRE usano percentuali più prudenti (3-3,5%) per aumentare il margine di sicurezza.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">È una stima statistica basata su dati storici passati (soprattutto mercato americano del Novecento), non una promessa: sequenze di rendimenti negativi nei primi anni di prelievo (il cosiddetto «sequence risk») possono ridurre la probabilità di successo. Molti nella comunità FIRE usano percentuali più prudenti (3-3,5%) per aumentare il margine di sicurezza.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Il numero FIRE con regole più o meno prudenti (migliaia di euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Spese annuali</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Prelievo 4%</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Prelievo 3,5%</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Prelievo 3%</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">20</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">500</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">571</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">667</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">30</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">750</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">857</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1.000</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">40</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1.000</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1.143</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1.333</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Capitale necessario = spese annuali diviso la percentuale di prelievo. Al 4% è 25 volte la spesa, al 3% oltre 33. Esempio: con 30.000 euro di spese servono 750.000 euro al 4% e 1 milione al 3%.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'indipendenza-finanziaria-fire-come-calcolare-il-numero' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Dividere le spese comuni esattamente a metà (50/50) sembra equo sulla carta, ma se i redditi sono molto diversi non lo è nella pratica: la stessa cifra pesa in modo molto diverso su chi guadagna meno. Un approccio più equo, usato spesso in questo modello ibrido, è versare sul conto comune una quota <strong>proporzionale al reddito</strong> di ciascuno, non un importo fisso identico — così entrambi contribuiscono con lo stesso sforzo relativo, non con la stessa cifra assoluta.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Dividere le spese comuni esattamente a metà (50/50) sembra equo sulla carta, ma se i redditi sono molto diversi non lo è nella pratica: la stessa cifra pesa in modo molto diverso su chi guadagna meno. Un approccio più equo, usato spesso in questo modello ibrido, è versare sul conto comune una quota <strong>proporzionale al reddito</strong> di ciascuno, non un importo fisso identico — così entrambi contribuiscono con lo stesso sforzo relativo, non con la stessa cifra assoluta.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Spese comuni di 1.800 euro, redditi di 3.000 e 1.500 euro (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5"></th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Versa A</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Versa B</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Peso sul reddito</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Metà a testa</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">900</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">900</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">30% / 60%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">In proporzione al reddito</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1.200</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">600</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">40% / 40%</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Con la divisione a metà B versa il 60% del suo reddito, A il 30%. In proporzione entrambi versano il 40%.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'finanze-di-coppia-conti-separati-o-cointestati' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il TFR lasciato in azienda viene rivalutato ogni anno con un tasso fisso dell''1,5% più il 75% dell''inflazione. È una rivalutazione prevedibile e senza rischi di mercato, che protegge abbastanza bene il potere d''acquisto ma raramente fa crescere il capitale in termini reali.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il TFR lasciato in azienda viene rivalutato ogni anno con un tasso fisso dell''1,5% più il 75% dell''inflazione. È una rivalutazione prevedibile e senza rischi di mercato, che protegge abbastanza bene il potere d''acquisto ma raramente fa crescere il capitale in termini reali.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Rivalutazione del TFR in azienda</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Inflazione</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Rivalutazione</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Rendimento reale</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">1%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">2,25%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">+1,25%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">2%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">3,00%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">+1,00%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">4%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">4,50%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">+0,50%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">8%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">7,50%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">−0,50%</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Rivalutazione = 1,5% + 75% dell''inflazione, prima delle tasse. Rendimento reale: rivalutazione meno inflazione. Con l''inflazione alta il TFR resta indietro.</p></figure>'),
    '<ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Tassazione finale agevolata</strong>: dal 15% al 9%, scendendo di 0,3 punti per ogni anno di partecipazione oltre il quindicesimo.</li><li><strong>Contributo del datore di lavoro</strong>: nei fondi negoziali di categoria, se versi anche un tuo contributo, spesso l''azienda aggiunge una quota che altrimenti non riceveresti.</li><li><strong>Deducibilità</strong> dei contributi aggiuntivi che versi di tasca tua, entro il limite annuo previsto dalla legge.</li></ul>',
    '<ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Tassazione finale agevolata</strong>: dal 15% al 9%, scendendo di 0,3 punti per ogni anno di partecipazione oltre il quindicesimo.</li><li><strong>Contributo del datore di lavoro</strong>: nei fondi negoziali di categoria, se versi anche un tuo contributo, spesso l''azienda aggiunge una quota che altrimenti non riceveresti.</li><li><strong>Deducibilità</strong> dei contributi aggiuntivi che versi di tasca tua, entro il limite annuo previsto dalla legge.</li></ul><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Tassazione finale del fondo pensione</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Anni di partecipazione</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Aliquota</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">15</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">15%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">20</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">13,5%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">25</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">12%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">30</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">10,5%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">35 o più</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">9%</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Dal sedicesimo anno l''aliquota scende di 0,3 punti l''anno, fino al minimo del 9%.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'tfr-in-azienda-o-fondo-pensione' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">La pensione non è più un concetto astratto. La priorità diventa ridurre gradualmente il rischio del portafoglio, verificare la propria posizione contributiva e stimare quanto servirà davvero. Il <a href="/news/ribilanciamento-portafoglio-cosa-e-perche" class="text-accent hover:underline font-medium">ribilanciamento</a> aiuta a mantenere il livello di rischio adatto all''orizzonte che si accorcia.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">La pensione non è più un concetto astratto. La priorità diventa ridurre gradualmente il rischio del portafoglio, verificare la propria posizione contributiva e stimare quanto servirà davvero. Il <a href="/news/ribilanciamento-portafoglio-cosa-e-perche" class="text-accent hover:underline font-medium">ribilanciamento</a> aiuta a mantenere il livello di rischio adatto all''orizzonte che si accorcia.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Le priorità decennio per decennio</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Età</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Priorità</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Da controllare</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">20 anni</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Abitudine al risparmio, primo fondo di emergenza</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Spese e debiti al consumo</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">30 anni</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Casa, famiglia, piano di accumulo, TFR</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Rapporto debito/reddito</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">40 anni</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Accelerare il risparmio, verso la pensione</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Tasso di risparmio e stile di vita</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">50 anni</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Ridurre il rischio, stimare la pensione</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Asset allocation e contributi</td></tr></tbody></table></div></figure>'),
    updated_at = NOW()
WHERE slug = 'gestire-i-soldi-a-20-30-40-50-anni' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Una volta assestato il bilancio, molte famiglie iniziano ad accantonare una piccola somma per il futuro del figlio, ad esempio per gli studi. Su orizzonti di quindici o vent''anni anche cifre modeste crescono in modo significativo grazie all''<a href="/news/interesse-composto-esempi-reali" class="text-accent hover:underline font-medium">interesse composto</a>, ad esempio con un <a href="/news/pac-piano-accumulo-etf-come-funziona" class="text-accent hover:underline font-medium">piano di accumulo</a>.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Una volta assestato il bilancio, molte famiglie iniziano ad accantonare una piccola somma per il futuro del figlio, ad esempio per gli studi. Su orizzonti di quindici o vent''anni anche cifre modeste crescono in modo significativo grazie all''<a href="/news/interesse-composto-esempi-reali" class="text-accent hover:underline font-medium">interesse composto</a>, ad esempio con un <a href="/news/pac-piano-accumulo-etf-come-funziona" class="text-accent hover:underline font-medium">piano di accumulo</a>.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">50 euro al mese per 18 anni (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Rendimento annuo</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Versato</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Capitale a 18 anni</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">0%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">10.800</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">10.800</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">2%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">10.800</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">12.987</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">4%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">10.800</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">15.780</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Rendimenti ipotetici, al netto dei costi e prima delle tasse. 0% è il salvadanaio, 4% un piano di accumulo diversificato.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'arrivo-di-un-figlio-pianificare-le-spese' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Le spese di acquisto si ammortizzano solo restando a lungo nella stessa casa. Se pensi di trasferirti entro pochi anni, l''affitto è spesso più conveniente; se ti vedi lì per dieci anni o più, l''acquisto tende a diventarlo.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Le spese di acquisto si ammortizzano solo restando a lungo nella stessa casa. Se pensi di trasferirti entro pochi anni, l''affitto è spesso più conveniente; se ti vedi lì per dieci anni o più, l''acquisto tende a diventarlo.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Costi che non tornano indietro, all''anno (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5"></th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Resti 5 anni</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Resti 10 anni</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Resti 20 anni</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Interessi del mutuo (media)</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">6.543</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">6.021</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">4.767</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Manutenzione (1% del valore)</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">2.500</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">2.500</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">2.500</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Rendimento perso sull''anticipo (3%)</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1.500</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1.500</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1.500</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Spese di acquisto divise per gli anni</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">3.000</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1.500</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">750</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Totale chi compra</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">13.543</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">11.521</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">9.517</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Affitto di una casa simile</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">10.800</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">10.800</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">10.800</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Esempio: casa da 250.000 euro, anticipo 50.000, mutuo di 200.000 a 25 anni al 3,5%, spese di acquisto di 15.000 euro, affitto di 900 euro al mese costante. Tasse sull''immobile, rivalutazione della casa e aumenti dell''affitto esclusi.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'comprare-o-affittare-casa-cosa-conviene' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
